const art=document.querySelector('#society-art'),ctx=art.getContext('2d'),pause=document.querySelector('#art-pause');let w=600,h=500,t=0,run=!matchMedia('(prefers-reduced-motion: reduce)').matches,last=0;const nodes=Array.from({length:95},(_,i)=>{const y=1-2*(i+.5)/95,r=Math.sqrt(1-y*y),a=i*2.399963;return{x:r*Math.cos(a),y,z:r*Math.sin(a)}});
function draw(){ctx.clearRect(0,0,w,h);const scale=Math.min(w*.36,h*.43),points=nodes.map(n=>{const x=n.x*Math.cos(t)-n.z*Math.sin(t),z=n.x*Math.sin(t)+n.z*Math.cos(t),y=n.y*Math.cos(.3)-z*Math.sin(.3),depth=n.y*Math.sin(.3)+z*Math.cos(.3),persp=3/(3-depth*.4);return{x:w*.56+x*scale*persp,y:h*.52+y*scale*persp,z:depth}});for(let i=0;i<nodes.length;i++){for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],d=Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z);if(d<.47){const v=(points[i].z+points[j].z)/2;ctx.strokeStyle='rgba(214,115,88,'+(.025+(v+1)*.06)+')';ctx.beginPath();ctx.moveTo(points[i].x,points[i].y);ctx.lineTo(points[j].x,points[j].y);ctx.stroke()}}}points.forEach((p,i)=>{ctx.fillStyle=i%9===0?'rgba(235,92,67,.85)':'rgba(208,177,151,'+(.15+(p.z+1)*.23)+')';ctx.beginPath();ctx.arc(p.x,p.y,i%9===0?2.5:1.25,0,Math.PI*2);ctx.fill()})}
new ResizeObserver(()=>{const r=art.getBoundingClientRect();w=r.width;h=r.height;art.width=w*devicePixelRatio;art.height=h*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);draw()}).observe(art);function sync(){pause.textContent=run?'Pause motion':'Play motion';pause.setAttribute('aria-label',run?'Pause background motion':'Play background motion')}pause.addEventListener('click',()=>{run=!run;sync()});function frame(ts){if(run&&!document.hidden&&ts-last>30){last=ts;t+=.0025;draw()}requestAnimationFrame(frame)}sync();requestAnimationFrame(frame);
